export const msmeShareStatusLabel = (level?: string | null): string => {
  if (level === 'filing_ready') return 'Ready to file';
  if (level === 'readiness_assessment') return 'Almost ready';
  return 'Ready to share (PDF)';
};

export const msmePdfDownloadLabel = (
  tabValue: number,
  readinessLevel?: string | null
): string => {
  const filingReady = readinessLevel === 'filing_ready';
  if (tabValue === REPORTING_TAB.CBAM) {
    return filingReady ? 'Download CBAM report (PDF)' : 'Download CBAM summary to share';
  }
  if (tabValue === REPORTING_TAB.ISO_14064) {
    return filingReady ? 'Download ISO inventory (PDF)' : 'Download inventory summary to share';
  }
  if (tabValue === REPORTING_TAB.ISO_14067) {
    return filingReady ? 'Download product footprint (PDF)' : 'Download product report to share';
  }
  return filingReady ? 'Download BRSR pack (PDF)' : 'Download report to share with buyer';
};

export const msmeStatutorySectionTitle = 'Official filing files';
export const msmeStatutorySectionSubtitle =
  'These unlock when your checklist passes. Use PDF above to share while you finish the remaining steps.';

export const msmeExportDialogIntro = 'Preview your report, then download what you need.';

export const remediationLinkForBlockedReason = (reason: string): string | null => {
  const text = reason.toLowerCase();
  if (/upload|bill|document|ocr|utility|electricity|fuel/.test(text)) {
    return DOCUMENT_UPLOAD_PATH;
  }
  if (/assessment|baseline|footprint|questionnaire/.test(text)) {
    return '/carbon-footprint?section=start-assessment';
  }
  if (/cbam|export|installation|registry/.test(text)) {
    return '/compliance/export';
  }
  if (/buyer|supplier|questionnaire|template/.test(text)) {
    return '/compliance';
  }
  if (/boundary|operations|manufacturing|product/.test(text)) {
    return '/operations';
  }
  if (/mitigation|reduction measure|abatement|selected action/.test(text)) {
    return '/emissions-reduction-targets?tab=2';
  }
  return '/compliance';
};

export const readinessRank = (level?: string | null): number => {
  const ranks: Record<ReportReadinessLevel, number> = {
    prep_draft: 0,
    readiness_assessment: 1,
    filing_ready: 2,
  };
  return ranks[(level as ReportReadinessLevel) || 'prep_draft'] ?? 0;
};

export const msmeProgressLabel = (score?: number | null): string => {
  const value = Math.round(Number(score) || 0);
  if (value >= 85) return `${value}% — you can unlock official files soon`;
  if (value >= 75) return `${value}% — a few steps left`;
  if (value >= 50) return `${value}% — upload bills to improve`;
  return `${value}% — start with assessment and 1–2 bills`;
};
